+            // of nextDoc():
+            long doc;
+            while (true) {
+                doc = docBuffer[docBufferUpto];
+
+                if (doc >= target) {
+                    break;
+                }
+                ++docBufferUpto;
+            }
+
+            docBufferUpto++;
+            return this.doc = (int) doc;
+        }
