+        private void skipPositions() throws IOException {
+            // Skip positions now:
+            int toSkip = posPendingCount - (int) freqBuffer[docBufferUpto - 1];
+            // if (DEBUG) {
+            // System.out.println(" FPR.skipPositions: toSkip=" + toSkip);
+            // }
