+                    badi.reset(impactData[level], 0, impactDataLength[level]);
+                    perLevelImpacts[level] = readImpacts(badi, perLevelImpacts[level]);
+                    impactDataLength[level] = 0;
+                }
+                return perLevelImpacts[level];
+            }
+        };
+    }
