+    static class MutableImpactList extends AbstractList<Impact> implements RandomAccess {
+        int length = 1;
+        Impact[] impacts = new Impact[] { new Impact(Integer.MAX_VALUE, 1L) };
+
+        @Override
+        public Impact get(int index) {
+            return impacts[index];
+        }
+
+        @Override
+        public int size() {
+            return length;
+        }
+    }
