+    /** Sets the values for the current skip data. */
+    public void bufferSkip(
+        int doc,
+        CompetitiveImpactAccumulator competitiveFreqNorms,
+        int numDocs,
+        long posFP,
+        long payFP,
+        int posBufferUpto,
